describe('Page Navigation', () => {
    beforeEach(() => {
        cy.visit('/'); // Replace with the actual URL of the application
    });

    it('should navigate to the specified page number', () => {
        const pageNumber = 3; // Example page number
        cy.get('input[name="page-number"]').type(pageNumber);
        cy.get('button[type="submit"]').click();
        cy.url().should('include', `page=${pageNumber}`);
        cy.get('.current-page').should('contain', pageNumber);
    });

    it('should show an error message for invalid page number', () => {
        const invalidPageNumber = -1; // Example of an invalid page number
        cy.get('input[name="page-number"]').type(invalidPageNumber);
        cy.get('button[type="submit"]').click();
        cy.get('.error-message').should('be.visible').and('contain', 'Invalid page number');
    });
});
